const float ic=1200*std::log2(hz/440.0f);if(!pitch_state_valid_){pitch_fast_cents_=pitch_slow_cents_=ic;pitch_state_valid_=true;vocal_target_.reset();}const float fa=1-std::exp(-1.0f/(.008f*sample_rate_)),sa=1-std::exp(-1.0f/(.110f*sample_rate_));pitch_fast_cents_+=(ic-pitch_fast_cents_)*fa;pitch_slow_cents_+=(pitch_fast_cents_-pitch_slow_cents_)*sa;const float residual=pitch_fast_cents_-pitch_slow_cents_;const float ofa=1-std::exp(-1.0f/(.003f*sample_rate_)),osa=1-std::exp(-1.0f/(.035f*sample_rate_));onset_fast_+=(std::abs(input)-onset_fast_)*ofa;onset_slow_+=(std::abs(input)-onset_slow_)*osa;const float onset=clamp((onset_fast_-onset_slow_)/std::max(.02f,onset_slow_*1.5f),0.0f,1.0f),motion=residual/.110f,target=vocal_target_.process(pitch_slow_cents_,motion,conf,onset);vocal_analysis_.observed_cents=ic;vocal_analysis_.center_cents=pitch_slow_cents_;vocal_analysis_.residual_cents=residual;vocal_analysis_.motion_cents_per_second=motion;vocal_analysis_.onset=onset;vocal_analysis_.stability=1-clamp(std::abs(motion)/600,0.0f,1.0f);vocal_analysis_.motion_intent=clamp(std::abs(motion)/300,0.0f,1.0f);vocal_analysis_.normalize_source_weights();vocal_analysis_.sanitize();
const float retained=pitch_slow_cents_+residual*c.vibrato_retention,desired=(target-retained)*c.correction_strength*(1-c.drift_retention),tm=2+(1-c.transition)*58;correction_cents_+=(desired-correction_cents_)*(1-std::exp(-1.0f/(tm*.001f*sample_rate_)));correction_cents_=clamp(sanitize(correction_cents_),-2400.0f,2400.0f);const float period=clamp(sample_rate_/hz,53.0f,872.0f),sm=c.sequential_stage_mix,pc=correction_cents_*(1-.5f*sm),sc=correction_cents_-pc;grain_phase_-=clamp(std::pow(2.0f,pc/1200),.25f,4.0f)/period;grain_phase_-=std::floor(grain_phase_);const float pb=grain_phase_<.5f?grain_phase_+.5f:grain_phase_-.5f,lag=clamp(period*1.15f,64.0f,float(RING_BUFFER_SIZE-900)),wa=std::sin(PI*grain_phase_),wb=std::sin(PI*pb);const float p1=ring_buffer_.read_interpolated(lag+grain_phase_*period)*wa*wa+ring_buffer_.read_interpolated(lag+pb*period)*wb*wb;vocal_stage_ring_buffer_.push(p1);secondary_grain_phase_-=clamp(std::pow(2.0f,sc/1200),.25f,4.0f)/period;secondary_grain_phase_-=std::floor(secondary_grain_phase_);const float sb=secondary_grain_phase_<.5f?secondary_grain_phase_+.5f:secondary_grain_phase_-.5f,w0=std::sin(PI*secondary_grain_phase_),w1=std::sin(PI*sb),p2=vocal_stage_ring_buffer_.read_interpolated(lag+secondary_grain_phase_*period)*w0*w0+vocal_stage_ring_buffer_.read_interpolated(lag+sb*period)*w1*w1,psola=lerp(p1,p2,sm);
